-- Consulta: Pagto Lote Financeira
-- Tipo: Seleção (0)
-- Descrição: 

SELECT [F Movimento Contas].EmpVinculada, EmpVinculada.NomeVinculada, [F Contas Financeiras].[Numero Conta], [F Movimento Contas].DataVencto, [F Movimento Contas].Plano1, [F Movimento Contas].Plano2, [F Movimento Contas].NumMovimento, [F Movimento Contas].ReferenteNotaFiscal, [F Movimento Contas].Efetuado, Historico.Descricao, EmpMaster.NomeMaster, Plano1.DescricaoPlano1, [F Movimento Contas].CodigoParceiro, [F Movimento Contas].CodHistorico, [F Movimento Contas].DataMovto, [F Movimento Contas].ValorDebito, Plano3.DescricaoPlano3, Plano2.DescricaoPlano2, [F Movimento Contas].ValorCredito, [F Movimento Contas].Complemento, [F Movimento Contas].Plano3, [F Movimento Contas].ContaFinanceira, [F Contas Financeiras].Descricao, [F Movimento Contas].Confirmado, [F Movimento Contas].Integracao, [F Movimento Contas].DataPagto, [F Movimento Contas].MovPagtoLote, [F Movimento Contas].SelPagtoLote, [F Movimento Contas].Observacao, [F Movimento Contas].NumDoc
FROM ((Plano1 INNER JOIN Plano2 ON Plano1.Plano1=Plano2.Plano1) INNER JOIN Plano3 ON Plano2.Plano2=Plano3.Plano2) INNER JOIN (Historico INNER JOIN ((EmpMaster INNER JOIN EmpVinculada ON EmpMaster.CodigoMaster=EmpVinculada.CodigoMaster) INNER JOIN ([F Contas Financeiras] INNER JOIN [F Movimento Contas] ON [F Contas Financeiras].CodigoConta=[F Movimento Contas].ContaFinanceira) ON EmpVinculada.CodigoVinculada=[F Movimento Contas].EmpVinculada) ON Historico.CodHistorico=[F Movimento Contas].CodHistorico) ON Plano3.Plano3=[F Movimento Contas].Plano3
ORDER BY [F Movimento Contas].EmpVinculada, [F Movimento Contas].DataVencto, [F Movimento Contas].CodigoParceiro;
